const input = $input.first()?.json ?? {};
const body = input.body ?? input;

return [{
  json: {
    config: {
      companyName: body.companyName || 'ABM Solutions Demo',
      senderName: body.senderName || 'Demo Sender',
      senderEmail: body.senderEmail || 'demo@example.com',
      slackWebhookUrl: body.slackWebhookUrl || 'REPLACE_WITH_SLACK_WEBHOOK_URL',
      hubspotToken: body.hubspotToken || 'REPLACE_WITH_HUBSPOT_PRIVATE_APP_TOKEN',
      openAiApiKey: body.openAiApiKey || 'REPLACE_WITH_OPENAI_API_KEY',
      demoMode: body.demoMode !== false
    },
    payload: body
  }
}];

const d=$input.first().json,l=d.lead;
const domain=l.email.split('@')[1]||'';
const seniority=/chief|cxo|vp|vice president/i.test(l.title)?'executive':/director|head/i.test(l.title)?'director':'individual';
let score=25+(l.employeeCount>=50?20:0)+(l.employeeCount>=200?15:0)+(seniority==='executive'?30:seniority==='director'?20:5);
score=Math.min(score,100);
return [{json:{...d,result:{...l,domain,seniority,companySize:l.employeeCount>=500?'enterprise':l.employeeCount>=50?'mid-market':'small-business',fitScore:score,fitTier:score>=80?'A':score>=60?'B':'C',enrichedAt:new Date().toISOString()}}}];
